const fs = require('fs');

if (process.argv.length < 3) {
  console.error('Usage: node patch_openapi_examples.js <openapi3.json>');
  process.exit(1);
}

const file = process.argv[2];
const doc = JSON.parse(fs.readFileSync(file, 'utf8'));

const examples = {
  text: {
    summary: "文本对话示例",
    value: {
      model: "qwen3-max",
      messages: [
        {
          role: "user",
          content: "hello"
        }
      ],
      temperature: 0.7,
      stream: false
    }
  },
  text_qwen: {
    summary: "千问下审核对话示例",
    value: {
      "model": "qwen3-max",
      "messages": [
        {
          "role": "user",
          "content": "千问下审核对话,请问你现在会检查合规内容吗?"
        }
      ],
      "temperature": 0.7,
      "stream": true,
      "X-DashScope-DataInspection":{
        "input": "disable",
        "output": "disable"
      }
    }
  },
  image: {
    summary: "图片理解示例",
    value: {
      model: "gpt-5.2-chat-latest",
      messages: [
        {
          role: "user",
          content: [
            {
              type: "text",
              text: "这张图片里有什么？"
            },
            {
              type: "image_url",
              image_url: {
                url: "https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png"
              }
            }
          ]
        }
      ],
      max_tokens: 300
    }
  },
  image_base64: {
    summary: "图片理解示例",
    value: {
      model: "gpt-5.2-chat-latest",
      messages: [
        {
          role: "user",
          content: [
            {
              type: "text",
              text: "这张图片里有什么？"
            },
            {
              type: "image_url",
              image_url: {
                url: "data:image/png;base64,"
              }
            }
          ]
        }
      ],
      max_tokens: 300
    }
  },
  video: {
    summary: "视频理解流式输出示例",
    value: {
      messages: [
        {
          role: "user",
          content: [
            {
              type: "video_url",
              video_url: {
                url: "https://www.w3school.com.cn/i/movie.mp4"
              }
            },
            {
              type: "text",
              text: "请描述这个视频的内容"
            }
          ]
        }
      ],
      model: "qwen3-omni-flash"
    }
  },
  file: {
    summary: "文件理解示例",
    value: {
      model: "gpt-5.2-chat-latest",
      messages: [
        {
          role: "user",
          content: [
            {
              type: "file",
              file: {
                filename:"example.pdf",
                file_data: "data:application/pdf;base64,"
              }
            },
            {
              type: "text",
              text: "请总结这份文件的主要内容"
            }
          ]
        }
      ],
      max_tokens: 400
    }
  },
  audio: {
    summary: "音频理解示例",
    value: {
      "model": "gpt-4o-audio-preview",
      "modalities": ["text", "audio"],
      "audio": { "voice": "alloy", "format": "wav" },
      "messages": [
        {
          "role": "user",
          "content": [
            { "type": "text", "text": "请描述这个音频的内容" },
            { "type": "input_audio", "input_audio": { "data":
                    "",
                "format": "wav" }}
          ]
        }
      ]
    }
  }
};

try {
  doc.paths["/v1/chat/completions"].post.requestBody.content["application/json"].examples = examples;
  const responsesJson = doc.paths?.["/v1/responses"]?.post?.requestBody?.content?.["application/json"];
  if (responsesJson) {
    responsesJson.example = {
      model: "doubao-seed-1-8-251228",
      input: "今天有什么新闻",
      tools: [
        {
          type: "web_search"
        }
      ],
      max_output_tokens: 1000,
      stream: false
    };
  }
  const embeddingsJson = doc.paths?.["/v1/embeddings"]?.post?.requestBody?.content?.["application/json"];
  if (embeddingsJson) {
    embeddingsJson.examples = {
      text: {
        summary: "文本向量",
        value: {
          model: "doubao-embedding-vision-251215",
          input: ["hello"],
          encoding_format: "float"
        }
      },
      multimodal: {
        summary: "多模态向量",
        value: {
          model: "doubao-embedding-vision-251215",
          input: [
            { type: "text", text: "hello" },
            { type: "image_url", image_url: { url: "https://ark-project.tos-cn-beijing.volces.com/doc_image/tower.png" } }
          ],
          encoding_format: "float"
        }
      }
    };
  }
  const rerankJson = doc.paths?.["/v1/rerank"]?.post?.requestBody?.content?.["application/json"];
  if (rerankJson) {
    rerankJson.examples = {
      text: {
        summary: "文本重排序示例",
        value: {
          model: "qwen3-rerank",
          query: "What is the capital of the United States?",
          documents: [
            "Carson City is the capital city of the American state of Nevada.",
            "The Commonwealth of the Northern Mariana Islands is a group of islands in the Pacific Ocean.",
            "Washington, D.C. is the capital of the United States."
          ],
          top_n: 2
        }
      },
      qwen3_vl_rerank: {
        summary: "qwen3-vl-rerank 多模态重排序示例",
        value: {
          model: "qwen3-vl-rerank",
          query: "什么是文本排序模型",
          documents: [
            { text: "文本排序模型广泛用于搜索引擎和推荐系统中，它们根据文本相关性对候选文本进行排序" },
            { image: "https://img.alicdn.com/imgextra/i3/O1CN01rdstgY1uiZWt8gqSL_!!6000000006071-0-tps-1970-356.jpg" },
            { video: "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20250107/lbcemt/new+video.mp4" }
          ],
          top_n: 2
        }
      }
    };
  }
  fs.writeFileSync(file, JSON.stringify(doc, null, 2));
  console.log("Patched openapi3.json with multi-examples for /v1/chat/completions, /v1/embeddings and /v1/rerank");
} catch (e) {
  console.error("Failed to patch openapi3.json:", e.message);
  process.exit(2);
} 
